"""Student, evidence, upload, and enrollment manuscript contracts."""
from api_contracts import P, ROSTER, YEAR, add

RECORD = "data: { student: { name, email, studentNumber, isOutsideOrg, createdAt }, year, enrollment, enrolledAt, steps, queue }"
EVIDENCE = "data: { evidence: [{ id, fileKey, fileUrl, kind, expiresAt, expired }] }"
add("GET", P+"/me/student/profile", "Read My Profile-Completion Status", response="data: { hasProfile, studentNumber }", notes="Does not require an active year.")
add("GET", P+"/students", "Search Students or Read the Roster", "Optional query: q (max 100), page (default 1), pageSize and limit (1–100, each default 50), cursor, sort, dir (asc/desc, default desc), role, outside, academicYearId, departmentId, yearLevel. "+ROSTER, "data: role-dependent directory, roster, or student-picker rows, with page/pageSize/total", "Staff only. Administrators normally receive the user directory; explicitly requesting scope, cursor, plural roster filters, enrolled, or unassigned selects roster mode. Advisers receive a cursor-based roster; page does not offset it. Officers receive a name/number picker, and blank q returns an empty list. Repeated query keys represent arrays; comma-separated strings are not split. Directory paging uses pageSize while metadata reports limit, so keep them equal. Roster scope all is an implemented filter, not a guarantee of department-only listing.", errors="403 for a student account.")
add("GET", P+"/students/board", "Read Roster Rows and Summary Together", ROSTER+" Optional cursor; limit 1–100, default 50.", "data: { roster: { data, page: 1, pageSize, total }, stats: { year, stats } }", "Adviser working area. The summary deliberately ignores bucket filters. Use only the documented step states; invalid states are not normalized consistently across rows and summaries.")
add("POST", P+"/students/reminders", "Send In-App Requirement Reminders", "Body: studentProfileIds (required array, 1–200 nonempty identifiers); academicYearId (optional).", "data: { sent, skipped }", "Deduplicates IDs. Skips missing users/profiles, completed students, and students placed in a department not assigned to the caller. An unplaced profile may still receive a reminder. This sends in-app notices, not email or SMS.", {"studentProfileIds":["profile-example"]}, "412 if the year cannot be resolved.")
add("GET", P+"/me/student", "Read My Enrollment Progress", response="data: { profile: { studentNumber, derivedStudentNumber, isOutsideOrg, enrollment, enrollments }, hasActiveYear, academicYearId, academicYearLabel, semesterLabel, steps, readyForQueue, allComplete, verifiedCount, progressPercent, queueStatus }", notes="Each step includes code/name/order/status, hint/chip, appliedAt, evidence, requirements, profilingFormUrl, socialMediaLinks, reply, and stamp. Missing profile/year is represented in the payload rather than automatically returning 412. No active year means null year fields and zero/false progress.")
add("PATCH", P+"/me/student", "Claim My Student Number", "Body: studentNumber (required trimmed, nonempty digits-only string).", "data: { studentNumber }", "Claims a missing profile; it does not replace an already-saved number. Existing profile numbers are returned unchanged. No fixed nine-digit limit is enforced.", {"studentNumber":"202600001"}, "412 without active year; 409 for a number already owned.")
add("GET", P+"/students/:id", "Read a Student's Enrollment Detail", "Path: id is a student-profile identifier. Optional query: academicYearId, scope (mine/all, default mine).", "data: { student, year, enrollment, steps, queue, pendingRequirements }", "Staff only. For advisers, mine checks assigned department when placement exists; all bypasses that particular scope check in the current implementation. Other staff use all. Do not describe this as unconditional department-only access.", errors="403 for a student or out-of-scope adviser; 404 missing profile; 412 unresolved year.")
add("GET", P+"/students/:id/record", "Read a Student's Record-Sheet Data", "Path: id is a student-profile identifier. Optional query: academicYearId, scope (mine/all, default mine).", RECORD, "Staff only, with the same adviser scope behavior as detail. Can return an incomplete record; unlike the student's own download, completion is not required. JSON supports website PDF generation.", errors="403 scope/access failure; 404 missing profile; 412 unresolved year.")
add("PUT", P+"/students/:id/mugshot", "Capture and Verify a Mugshot", "Path: id is a step-verification identifier, despite the students path. Body: fileKey (required string, 1–500 characters), fileUrl (required string, 1–2,000,000 characters).", "data: { verificationId, status: VERIFIED, uploadId }", "Officer working area. The fileUrl field is not URL-validated here. Creates an upload, attaches it, and immediately verifies the mugshot step; do not send a student-profile ID as id.", {"fileKey":"capture-example","fileUrl":"https://example.org/demo-photo.jpg"}, "404 missing verification; 412 no active year; 409 wrong step, archived year, or already verified.")
add("GET", P+"/me/record", "Read My Completed Enrollment Record", response=RECORD+", or null", notes="Returns null unless the active year's enrollment step is verified. No profile/year also produces null. JSON is formatted as a PDF by the website.")
add("POST", P+"/me/assessment", "Request Assessment Review", response="data: { status: APPLIED }, or { status: VERIFIED } if already verified", notes="No evidence-upload body is required. Internally this creates or reopens pending assessment review; do not infer the saved status from the APPLIED response alone.", errors="412 no active year/profile; 404 assessment step not configured.")
add("POST", P+"/evidence", "Attach File Metadata to a Requirement", "Body: stepCode (SOCIAL_MEDIA/PROFILING/MUGSHOT/CONSENT), fileKey (1–500 characters), fileUrl (valid URL, at most 1,000 characters), all required.", EVIDENCE, "Records the supplied key/URL; this call does not verify stored bytes exist. Without a verification, returns the new draft; with one, returns attached evidence. Adding to a returned verification changes it to submitted.", {"stepCode":"SOCIAL_MEDIA","fileKey":"demo-file","fileUrl":"https://example.org/demo-evidence.png"}, "404 step not configured; 409 if verified, including a concurrent verification.", 201)
add("DELETE", P+"/evidence/:id", "Delete My Upload Metadata", "Path: id is the upload identifier.", "data: { deleted: true }", "Checks ownership and verified-step restrictions. Removes the upload row; existing verification identifier references are not rewritten by this handler. Object deletion is best-effort.", errors="404 absent/not owned; 409 if protected by verified active-year work.")
add("PUT", P+"/me/evidence-link", "Save an External Evidence Link", "Body: stepCode (SOCIAL_MEDIA/PROFILING/MUGSHOT/CONSENT), url (valid URL, at most 1,000 characters), both required.", EVIDENCE, "Stores/upserts the link but does not itself create a verification or submit the requirement. Returns all external links for the profile, not only this step. A different URL adds another link. This handler does not itself reject a verified step.", {"stepCode":"SOCIAL_MEDIA","url":"https://example.org/demo-proof"})
add("DELETE", P+"/me/evidence-link", "Remove External Evidence Links", "Body: stepCode (required upload-capable step code).", EVIDENCE, "Without a verification, removes links for that step and returns remaining file drafts of that kind. With a verification, removes its referenced external links and may delete an empty verification.", {"stepCode":"SOCIAL_MEDIA"}, "404 if step is not configured; 409 if verified.")
add("POST", P+"/me/steps/:code/submission", "Submit a Requirement for Review", "Path: code is SOCIAL_MEDIA, PROFILING, MUGSHOT, or CONSENT. No business body fields.", "data: { status: SUBMITTED, evidence: [...] }", "For profiling, checks the latest Google Form response matching the session email; screenshots/links are not the profiling completion check. Other steps collect eligible non-expired uploads and step links. Profiling evidence may be empty.", errors="404 unconfigured step; 409 verified; 412 absent/expired evidence, missing form, or no matching response; 503 Forms disabled.", status=201)
add("DELETE", P+"/me/steps/:code/submission", "Cancel a Submitted Requirement", "Path: code is an upload-capable step. No business body fields.", "data: { status: PENDING }", "Deletes a submitted verification and retains eligible file evidence as drafts with a fresh 24-hour expiry.", errors="404 step/submission missing; 409 unless status is submitted.")
add("POST", P+"/storage/session", "Start an Authorized Upload", "Body: route (evidenceImage/mugshotCapture/stampImage), mime (string, max 100), size (positive integer bytes), all required. evidenceImage requires stepCode and forbids studentProfileId. mugshotCapture and stampImage require studentProfileId. Supported MIME: image/jpeg, image/png, image/webp, application/pdf. Effective caps: 10 MiB evidence/mugshot, 5 MiB stamp (even though the generic size schema allows up to 100 MiB).", "data: { uploadId, uploadUrl, sessionExpiresAt }", "Student-facing access for evidenceImage; officer access for capture/stamp. Requires active year and applicable profile/email ownership checks. Student upload email must be the university student domain; officer-target uploads require a student with that domain. Upload directly to the returned URL, then finalize. Sessions last 24 hours. Twenty mint requests per minute per user/IP. Storage outages/quotas return a direct { code: STORAGE_QUOTA_EXCEEDED, message } body, not the standard error wrapper.", {"route":"evidenceImage","stepCode":"SOCIAL_MEDIA","mime":"image/png","size":1024}, "400 invalid route fields; 403 role/owner/email; 404 profile/step; 409 verified step; 412 no active year/profile; 413 file too large; 415 MIME unsupported; 429 limit; 502 presign failure; 503 disabled/paused storage or byte/operation quota.", 201)
add("POST", P+"/storage/complete", "Finalize an Upload", "Body: uploadId (required); stepCode (optional string, 1–64 characters).", "data: { id, fileKey, fileUrl, kind, expiresAt, expired: false }", "Checks visibility and stored object metadata. Normal object-storage completion uses fileKey with a storage reference and fileUrl null. Repeated completion of an already-complete row is accepted. An expired timestamp alone is not an explicit rejection in this handler; do not rely on it as an expiry-enforcement promise.", {"uploadId":"upload-example","stepCode":"SOCIAL_MEDIA"}, "403 not visible; 404 upload/bytes absent; 400 conflicting step; 409 wrong backend; 422 MIME/size verification failure.")
add("GET", P+"/storage/session-status", "Read Upload Session Status", "Required query: uploadId.", "data: { status: pending|complete|abandoned, bytesReceived?, r2Key? }", "Uploader, profile owner, officer, and administrator have applicable visibility. Advisers have department-related visibility and some unplaced-student access; this is not access to all uploads. bytesReceived is conditional. Time expiry alone does not change status here.", errors="403 not visible; 404 unknown upload.")
add("GET", P+"/uploads/:id/content", "Read Authorized File Content", "Path: id is the upload identifier. Optional HTTP Range header.", "200 or 206 binary file content, not a JSON envelope", "Uses the upload visibility checks. Content-Disposition is inline; storage MIME and range headers are forwarded when available. Current cache policy is private, immutable for one year. Missing/non-storage rows fall through to not-found handling.", errors="403 unauthorized; 404 missing/unusable upload.")
add("GET", P+"/me/enrollments", "List My Enrollment Periods", response="data: [{ academicYearId, academicYearLabel, semesterLabel, departmentId, departmentName, departmentCode, yearLevel, isActiveYear }], page: 1, pageSize: row count, total: row count", notes="No consumed paging query. Sorted by enrollment-period creation time. No profile returns an empty list.")
add("POST", P+"/me/enrollments", "Save My Enrollment Placement", "Body: academicYearId, departmentId, yearLevel (all required). Optional studentNumber (trimmed digits-only string). "+YEAR, "data: { enrollment, studentNumber }", "Accepts an existing year, not only the active year. Existing number is retained. Changed placement is refused if a queue entry exists, including completed entries. Unchanged placement is accepted without the change checks.", {"academicYearId":"year-example","departmentId":"department-example","yearLevel":"FIRST","studentNumber":"202600001"}, "400 invalid year/department/level or missing number; 409 number collision or changed placement with queue activity.")
add("POST", P+"/enrollments/:id/completion", "Complete Enrollment from a Queue Entry", "Path: id is a queue-entry identifier, not a student-profile or placement identifier. Body: departmentId (required).", "data: { entryId, studentName, outcome: enrolled|already }", "Checks current-year department/year-level responsibility and the current serving adviser. Completed entries can return outcome already after permission checks.", {"departmentId":"department-example"}, "403 assignment/current-server failure; 404 missing/wrong department entry; 409 wrong year/status, missing verified prerequisites, or concurrent transition; 412 no active year.")
add("DELETE", P+"/enrollments/:id/completion", "Revert One Completed Enrollment", "Path: id is a queue-entry identifier. Body: departmentId and reason (10–500 characters), both required.", "data: { enrollmentId, reverted: true, returnedEntryId }", "Returns the same entry to the front of the waiting line and withdraws enrollment verification.", {"departmentId":"department-example","reason":"Enrollment marked complete in error."}, "403 assignment failure; 404 missing entry; 409 wrong year/not completed/racing update; 412 no active year.")
add("DELETE", P+"/enrollments/completions", "Revert Multiple Completed Enrollments", "Body: departmentId and reason (10–500 characters), required. Supply enrollmentIds and/or ids arrays; combine to 1–50 distinct queue-entry identifiers.", "data: { revertedCount, revertedIds, returnedEntryIds }", "Validates entries before sequential reversions. It is not a multi-record all-or-nothing database transaction.", {"departmentId":"department-example","enrollmentIds":["queue-example"],"reason":"Enrollment marked complete in error."}, "400 empty/over-limit selection; same permission/state errors as individual reversion.")
add("GET", P+"/submissions", "List Requirement Submissions", __import__('api_contracts').SUBMISSIONS, "data: submission rows, with list metadata")
add("GET", P+"/submissions/:verificationId", "Read a Submission in Full", "Path: verificationId is a step-verification identifier.", "data: { verificationId, step, student, status, submittedAt, appliedAt, answers, evidence, requirements, stamp, ...review history }", errors="404 if missing.")
add("POST", P+"/submissions/:id/verification", "Verify a Submission", "Path: id is a step-verification identifier. No business body fields.", "data: { verificationId, status: VERIFIED }", "Uses the officer's configured stamp; saved stamp changes use the separate stamp endpoint.", errors="404 missing submission; 409 unsuitable review state or year.")
add("DELETE", P+"/submissions/:id/verification", "Withdraw a Verification", "Path: id is a step-verification identifier. No business body fields.", "data: { verificationId, status: PENDING }", errors="404 missing submission; 409 unsuitable review state or year.")
add("POST", P+"/submissions/:id/replies", "Return a Submission with Feedback", "Path: id is a step-verification identifier. Body: chips (optional nonempty strings, at most ten, default []), note (optional string, max 500).", "data: { verificationId, status: RETURNED }", example={"chips":["Unreadable evidence"],"note":"Please submit a clearer image."}, errors="404 missing submission; 409 unsuitable review state or year.")
